using System.IO;
using System.Reflection;
using System.Text.Json;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program {
 static int checks;static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}static readonly string Dir=Directory.GetCurrentDirectory();
 static Dictionary<string,JsonElement> Parameters(RotateCalibrationPlugin p,string path){var d=p.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());d["FilePath"]=JsonSerializer.SerializeToElement(path);return d;}
 static RotateCalibrationSession Session(RotateCalibrationPlugin p,string node,ModuleExecutionScope? scope=null){var state=typeof(RotateCalibrationPlugin).GetMethod("Get",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(p,[node,Dir,scope])!;return (RotateCalibrationSession)state.GetType().GetField("Session")!.GetValue(state)!;}
 static int Main(){try{var fixture=Path.GetFullPath("analysis/rotate-calibration/typed-input-checks/matrix.iwcal");Directory.CreateDirectory(Path.GetDirectoryName(fixture)!);Oracle(fixture);Matrix(fixture);Graph(fixture);Scope(fixture);Console.WriteLine($"PASS {checks}: Rotate original typed read gates/order and actual Graph numeric/integer arrays");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Matrix(string file)=>File.WriteAllBytes(file,new float[]{2,0,10,0,2,-5,0,0,1}.SelectMany(BitConverter.GetBytes).ToArray());
 static void Oracle(string file){foreach(string line in File.ReadLines("analysis/rotate-calibration/typed-input-oracle/run-b0c8ff040efd42218b3c94850eb1eea8/probe.jsonl")){using var doc=JsonDocument.Parse(line);var row=doc.RootElement;var phase=row.GetProperty("phase").GetString()!;if(!phase.StartsWith("typed-"))continue;int test=int.Parse(phase[6..]);Matrix(file);var p=new RotateCalibrationPlugin();var calls=new List<string>();
  ModuleIntegerInputReadResult? Int(string name,int index){Check(index==0,"original int index0");calls.Add(name);if(name=="RefreshSignal"&&test==9)return new(0xe0000123,0,1);if(name=="RefreshSignal"&&test is 12 or 13){File.Delete(file);return new(test==12?0:0xe0000123u,0,1);}if(name=="RotNum"&&test is 7 or 8)return new(test==7?0xe0000123u:0,0,3);return new(0,2,name=="RotNum"?(test==10?2:3):0);}
  ModuleNumericInputReadResult? Float(string name,int index){Check(index==0,"original float index0");calls.Add(name);int ordinal=name=="ImagePointX"?1:name=="ImagePointY"?2:3;if(test==ordinal)return new(0xe0000123,0,0);if(test==ordinal+3)return new(0,0,999);return new(0,2,name=="ImagePointX"?50:name=="ImagePointY"?40:17);}
  var actual=p.CreateRuntime().ExecuteAsync(new("native",Dir,new Dictionary<string,PortValue>(),Parameters(p,test==11?"":file)){ReadIntegerInput=Int,ReadNumericInput=Float},default).Result;var state=Session(p,"native");Check(actual.NativeErrorCode==row.GetProperty("code").GetUInt32(),"native return "+phase);Check(state.Current==row.GetProperty("current").GetInt32()&&state.Total==row.GetProperty("total").GetInt32()&&state.Remaining==row.GetProperty("remain").GetInt32(),"native state "+phase);Check(calls.SequenceEqual(row.GetProperty("getters").EnumerateArray().Select(x=>x.GetProperty("name").GetString()!)),"native exact gated read sequence "+phase);
  var writes=row.GetProperty("writes").EnumerateArray().ToArray();Check(actual.Outputs.Count==writes.Length+1,"native output presence plus forced timing "+phase);foreach(var write in writes){string name=write.GetProperty("name").GetString()!;double expected=write.GetProperty("values")[0].GetDouble();var value=actual.Outputs[name];Check((value.Kind==DataKind.Integer?value.As<long>():value.As<double>())==expected,"native field "+phase+"/"+name);}
 }}
 static void Graph(string file){foreach(var (countIndex,xIndex,refreshIndex,expected,total) in new (string?,string?,string?,uint,int)[]{(null,null,null,0,3),("1","1",null,0,5),("9",null,null,0xe0000001,0),("-1",null,null,0xe0000001,0),(null,"9",null,0xe0000014,3),(null,"-1",null,0xe0000014,3),(null,null,"1",0,3),(null,null,"9",0,3),(null,null,"-1",0,3)}){
  var p=new RotateCalibrationPlugin();var registry=new ModuleRegistry();registry.Register(p.Descriptor,p.CreateRuntime);registry.Register(Source.Definition,()=>new Source());WorkflowSubscription Bind(string input,string output,string? index)=>new("rotate",input,false,new(WorkflowSourceKind.NodeOutput,"source",output){ArrayIndex=index is null?null:new(index)});var flow=new ProcedureDocument("rotate-typed","rotate-typed",[new("source",Source.Id,"1","source",[]),new("rotate",RotateCalibrationPlugin.Id,"1.0.0","rotate",Parameters(p,file))],[],[new("source","rotate")]){Configuration=new(){Subscriptions=[Bind("RotNum","Count",countIndex),Bind("RefreshSignal","Refresh",refreshIndex),Bind("ImagePointX","X",xIndex),Bind("ImagePointY","Y",null),Bind("WorldRotateAngle","A",null)]}};Check(GraphValidator.Validate(flow,registry).IsValid,"actual Graph typed array contract");using var scope=new ModuleExecutionScope();var result=new GraphExecutor(registry).RunAsync(flow,Dir,scope:scope).Result;var node=result.Nodes.Single(n=>n.NodeId=="rotate");Check(node.NativeErrorCode==expected,"actual Graph native code "+countIndex+"/"+xIndex+"/"+refreshIndex);Check(Session(p,"rotate",scope.ForProcedure(flow.Id)).Total==total,"actual Graph index-specific count");if(expected==0)Check(node.Outputs["remainCount"].As<long>()==total-1,"actual Graph scalar native first-read output");
 }}
 static void Scope(string file){var p=new RotateCalibrationPlugin();using var scope=new ModuleExecutionScope();var reader=new ScopeReader();scope.RegisterService<IToolNumericInputReader>(reader);scope.RegisterService<IToolIntegerInputReader>(reader);var result=p.CreateRuntime().ExecuteAsync(new ModuleExecutionContext("scope",Dir,new Dictionary<string,PortValue>(),Parameters(p,file)){Scope=scope,ReadNumericInput=(_,_)=>throw new Exception("numeric priority"),ReadIntegerInput=(_,_)=>throw new Exception("integer priority")},default).Result;Check(result.NativeErrorCode==0&&result.Outputs["remainCount"].As<long>()==2,"Scope integer/numeric services precede deferred/materialized");Check(reader.Calls.SequenceEqual(new[]{"RefreshSignal:0","RotNum:0","ImagePointX:0","ImagePointY:0","WorldRotateAngle:0"}),"Scope exact primitive read order");}
 sealed class ScopeReader:IToolNumericInputReader,IToolIntegerInputReader{public List<string> Calls=[];ToolNumericInputReadResult IToolNumericInputReader.Read(ModuleExecutionContext c,string name,int index){Calls.Add(name+":"+index);return new(0,2,10);}ToolIntegerInputReadResult IToolIntegerInputReader.Read(ModuleExecutionContext c,string name,int index){Calls.Add(name+":"+index);return new(0,2,name=="RotNum"?3:0);}}
 sealed class Source:IModule{public const string Id="test.rotate.typed";public static ModuleDescriptor Definition{get;}=new(Id,"1","source",[],[new("X",DataKind.NumberArray),new("Y",DataKind.NumberArray),new("A",DataKind.NumberArray),new("Count",DataKind.Integer){Cardinality=ValueCardinality.Array},new("Refresh",DataKind.Integer){Cardinality=ValueCardinality.Array}],[]);public ModuleDescriptor Descriptor=>Definition;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken t)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"X",PortValue.Numbers([50,80])},{"Y",PortValue.Numbers([40,90])},{"A",PortValue.Numbers([17,60])},{"Count",PortValue.IntegerArray([3,5])},{"Refresh",PortValue.IntegerArray([0,1])}}));}
}
